INSERT INTO blog_articles (id, title, slug, content, excerpt, author, category, featured, published_at, created_at, updated_at) VALUES
  ('aa0e8400-e29b-41d4-a716-446655440001', '10 Tips for Healthy Living in 2025', '10-tips-healthy-living-2025', 'Regular exercise, balanced diet, and sufficient sleep are key to maintaining good health. Stay hydrated, reduce stress, and get regular health checkups. Here are 10 essential tips for living a healthy life in 2025.', 'Discover 10 essential tips for maintaining good health and wellness throughout 2025.', 'Dr. Health Expert', 'Wellness', true, NOW(), NOW(), NOW()),
  ('aa0e8400-e29b-41d4-a716-446655440002', 'Understanding Your Blood Test Results', 'understanding-blood-test-results', 'Blood tests are crucial for detecting diseases early. Learn what your CBC, lipid profile, and glucose levels mean. Understanding your test results helps you take better control of your health.', 'A comprehensive guide to understanding common blood test results and what they indicate about your health.', 'Dr. Lab Specialist', 'Health Education', true, NOW(), NOW(), NOW()),
  ('aa0e8400-e29b-41d4-a716-446655440003', 'Cardiac Health: Prevention is Better Than Cure', 'cardiac-health-prevention', 'Heart disease is the leading cause of death. Regular cardiac checkups, exercise, and a healthy diet can save your life. Prevention is always better than cure when it comes to heart health.', 'Learn about cardiac health, risk factors, and preventive measures to keep your heart healthy.', 'Dr. Cardiologist', 'Heart Health', true, NOW(), NOW(), NOW()),
  ('aa0e8400-e29b-41d4-a716-446655440004', 'Women''s Health: Monthly Health Checkup Guide', 'womens-health-checkup-guide', 'Women have unique health needs. Regular gynecological checkups, breast screening, and bone density tests are essential. Monthly health monitoring ensures early detection of any issues.', 'A complete guide to women''s health checkups and screening tests recommended at different ages.', 'Dr. Gynecologist', 'Women''s Health', true, NOW(), NOW(), NOW()),
  ('aa0e8400-e29b-41d4-a716-446655440005', 'COVID-19 Recovery: Health Monitoring Guide', 'covid-recovery-monitoring', 'After COVID-19 recovery, continue monitoring your health with regular checkups to ensure complete recovery. Post-COVID health monitoring is critical for long-term wellness.', 'Complete guide on monitoring your health after COVID-19 recovery and managing post-COVID symptoms.', 'Dr. COVID Specialist', 'Recent Updates', true, NOW(), NOW(), NOW());
