-- CATEGORIES (actual schema: id, name, type, created_at, updated_at)
DELETE FROM categories WHERE name IN ('General Health', 'Cardiac Health', 'Women''s Health', 'Wellness Packages', 'Full Body Checkup', 'COVID-19 Tests');

-- LAB TESTS (schema: id, name, price, mrp, category_id, description, features, report_time, home_collection, created_at, updated_at)
DELETE FROM lab_tests WHERE name IN ('Complete Blood Count (CBC)', 'Lipid Profile', 'Liver Function Test (LFT)', 'Kidney Function Test (KFT)', 'Thyroid Profile', 'Blood Sugar (Fasting & PP)', 'ECG', 'Chest X-Ray', 'Vitamin D Test', 'Iron Panel');

-- HEALTH PACKAGES (schema: id, name, price, mrp, category_id, description, includes, created_at, updated_at)
DELETE FROM health_packages WHERE name IN ('Basic Health Checkup', 'Comprehensive Health Checkup', 'Cardiac Health Checkup', 'Women''s Health Checkup', 'Senior Wellness Package');

-- PROMO CODES (schema: id, code, discount_type, discount_value, min_order_amount, usage_limit, usage_count, valid_from, valid_until, max_discount, is_active, description, created_at, updated_at)
DELETE FROM promo_codes WHERE code IN ('WELCOME50', 'HEALTH20', 'SENIOR30', 'SAVE500', 'MONSOON15');

